// Step 1: Select or create a database
use school_db                                          // database switch karo

// Step 2: Create collection explicitly
db.createCollection('students')                        // naya collection banao

// Create with validation (optional)
db.createCollection('orders', {                        // naya collection banao
  validator: {
    $jsonSchema: {
      bsonType: 'object',
      required: ['name', 'email'],
      properties: {
        name:  { bsonType: 'string' },
        email: { bsonType: 'string' }
      }
    }
  }
})

// Auto-create on first insert (no explicit createCollection needed)
db.products.insertOne({ name: 'Laptop', price: 50000 }) // ek document insert karo

// Utility commands
show dbs           // list all databases
show collections   // list collections in current db
db.stats()         // database statistics

// ── insertOne: add a single document ──────────────────────────
db.students.insertOne({                                // ek document insert karo
    name:      'Alice',              // string field
    age:       20,                   // number field
    class:     '10th',               // class string
    marks:     92.5,                 // decimal number
    email:     'alice@example.com',  // unique identifier
    subjects:  ['Math', 'Physics'],  // array field (list of values)
    address:   { city: 'Mumbai', state: 'MH' },  // embedded document (nested object)
    createdAt: new Date()            // current date/time
})
// Returns: { acknowledged: true, insertedId: ObjectId("...") }

// ── insertMany: add multiple documents at once ────────────────
db.students.insertMany([                               // multiple documents insert karo
    { name: 'Bob',     age: 21, class: '11th', marks: 78.0 },   // first document
    { name: 'Charlie', age: 19, class: '10th', marks: 85.5 },   // second document
    { name: 'Diana',   age: 20, class: '12th', marks: 91.0 },   // third document
    { name: 'Evan',    age: 22, class: '11th', marks: 74.5 }    // fourth document
])
// Returns: { acknowledged: true, insertedIds: { 0: ObjectId, 1: ObjectId, ... } }

// ── Continue on error: ordered: false ─────────────────────────
// By default (ordered: true), insertMany stops on first error
// With ordered: false, it continues and reports all errors at end
db.students.insertMany(docs, { ordered: false })       // multiple documents insert karo

// Find all documents
db.students.find()                                     // documents dhundo

// Pretty print (readable format)
db.students.find().pretty()                            // documents dhundo

// Find with condition (equal)
db.students.find({ class: '10th' })                    // documents dhundo

// Find with comparison
db.students.find({ marks: { $gt: 80 } })               // documents dhundo

// Multiple conditions (AND by default)
db.students.find({ marks: { $gt: 75 }, class: '10th' }) // documents dhundo

// Find one document
db.students.findOne({ name: 'Alice' })                 // ek document dhundo

// Count matching documents
db.students.countDocuments({ marks: { $gt: 80 } })     // greater than

// Find with projection (show only name and marks, hide _id)
db.students.find(                                      // documents dhundo
  { marks: { $gt: 80 } },                              // greater than
  { name: 1, marks: 1, _id: 0 }
)

// Comparison operators
db.students.find({ marks: { $gt:  80 } })  // marks > 80
db.students.find({ marks: { $gte: 80 } })  // marks >= 80
db.students.find({ marks: { $lt:  50 } })  // marks < 50
db.students.find({ marks: { $lte: 50 } })  // marks <= 50
db.students.find({ marks: { $ne:  0  } })  // marks != 0

// IN and NOT IN
db.students.find({ age: { $in:  [19, 20, 21] } })  // age IN list
db.students.find({ age: { $nin: [19, 20] } })       // age NOT IN list

// OR condition
db.students.find({                                     // documents dhundo
  $or: [                                               // any ek condition True ho
    { marks: { $gt: 90 } },                            // greater than
    { class: '12th' }
  ]
})

// AND condition (explicit)
db.students.find({                                     // documents dhundo
  $and: [                                              // dono conditions True hon
    { marks: { $gt: 70 } },                            // greater than
    { marks: { $lt: 90 } }                             // less than
  ]
})

// NOR: none of the conditions
db.students.find({                                     // documents dhundo
  $nor: [{ class: '10th' }, { marks: { $lt: 50 } }]    // less than
})

// LIKE (regex pattern)
db.students.find({ name: /^Al/i })   // starts with Al (case insensitive)
db.students.find({ name: /ali/i })   // contains 'ali'

// Sort ascending (1 = ASC)
db.students.find().sort({ name: 1 })                   // documents dhundo

// Sort descending (-1 = DESC)
db.students.find().sort({ marks: -1 })                 // documents dhundo

// Sort by multiple fields
db.students.find().sort({ class: 1, marks: -1 })       // documents dhundo

// Limit results
db.students.find().limit(5)                            // documents dhundo

// Skip records (for pagination)
db.students.find().skip(10).limit(5)   // page 3 (5 per page)

// Top 3 students by marks
db.students.find(                                      // documents dhundo
  {},
  { name: 1, marks: 1, _id: 0 }
).sort({ marks: -1 }).limit(3)

// Pagination helper
const page = 2
const pageSize = 10
db.students.find().skip((page-1) * pageSize).limit(pageSize) // documents dhundo

// Update single field (updateOne)
db.students.updateOne(                                 // ek document update karo
  { name: 'Alice' },         // filter
  { $set: { marks: 97 } }    // update
)

// Update multiple fields
db.students.updateOne(                                 // ek document update karo
  { name: 'Alice' },
  {
    $set: { marks: 99, grade: 'A+' },                  // field update karo
    $currentDate: { updatedAt: true }
  }
)

// Increment a field
db.students.updateOne(                                 // ek document update karo
  { name: 'Bob' },
  { $inc: { marks: 5 } }   // increase marks by 5
)

// Update many documents
db.students.updateMany(                                // multiple documents update karo
  { marks: { $lt: 50 } },  // filter: all failing students
  { $set: { status: 'fail' } }                         // field update karo
)

// Push element to array
db.students.updateOne(                                 // ek document update karo
  { name: 'Alice' },
  { $push: { subjects: 'Chemistry' } }                 // array mein add karo
)

// Pull (remove) element from array
db.students.updateOne(                                 // ek document update karo
  { name: 'Alice' },
  { $pull: { subjects: 'Math' } }
)

// Upsert: insert if not found
db.students.updateOne(                                 // ek document update karo
  { email: 'new@example.com' },
  { $set: { name: 'New Student', age: 20 } },          // field update karo
  { upsert: true }  // creates new doc if filter not found
)

// Delete one matching document
db.students.deleteOne({ name: 'Alice' })               // ek document delete karo

// Delete all matching documents
db.students.deleteMany({ marks: { $lt: 33 } })         // multiple documents delete karo

// Delete all documents (collection stays)
db.students.deleteMany({})                             // multiple documents delete karo

// Drop entire collection
db.students.drop()                                     // collection delete karo

// Drop entire database
db.dropDatabase()                                      // database delete karo

// WARNING: deleteMany({}) deletes ALL documents!
// Always test your filter with find() first:
db.students.find({ marks: { $lt: 33 } })  // preview first
db.students.deleteMany({ marks: { $lt: 33 } })  // then delete

// Count and average per class
db.students.aggregate([                                // aggregation pipeline chalo
  { $group: {                                          // documents group karo
      _id: '$class',
      count:      { $sum: 1 },                         // sum nikalo
      avgMarks:   { $avg: '$marks' },                  // average nikalo
      totalMarks: { $sum: '$marks' },                  // sum nikalo
      maxMarks:   { $max: '$marks' },                  // maximum value
      minMarks:   { $min: '$marks' }                   // minimum value
  }},
  { $sort: { count: -1 } }                             // documents sort karo
])

// Full pipeline: filter → transform → sort → limit
db.students.aggregate([                                // aggregation pipeline chalo
  // Stage 1: Filter (like WHERE)
  { $match: { marks: { $gte: 60 } } },                 // documents filter karo

  // Stage 2: Add computed field
  { $project: {                                        // fields select karo
      name:  1,
      marks: 1,
      grade: { $cond: [{ $gte: ['$marks', 90] }, 'A', 'B'] } // greater than or equal
  }},

  // Stage 3: Sort
  { $sort: { marks: -1 } },                            // documents sort karo

  // Stage 4: Limit results
  { $limit: 10 }                                       // result limit karo
])

// TIP: Use $match early in pipeline to filter before $group for performance

// $lookup = JOIN in MongoDB
// Join orders with users collection
db.orders.aggregate([                                  // aggregation pipeline chalo
  {
    $lookup: {                                         // doosre collection se join karo
      from:         'users',      // collection to join
      localField:   'user_id',    // field in orders
      foreignField: '_id',        // field in users
      as:           'user_info'   // output array field name
    }
  },

  // $unwind: flatten the array (1 doc per order)
  { $unwind: '$user_info' },                           // array ko flat karo

  // Project only needed fields
  {
    $project: {                                        // fields select karo
      order_id: 1,
      amount:   1,
      'user_info.name':  1,
      'user_info.email': 1
    }
  },

  // Sort by amount
  { $sort: { amount: -1 } }                            // documents sort karo
])

// Multiple lookups
db.orders.aggregate([                                  // aggregation pipeline chalo
  { $lookup: { from: 'users',    localField: 'user_id',    foreignField: '_id', as: 'user' }}, // doosre collection se join karo
  { $lookup: { from: 'products', localField: 'product_id', foreignField: '_id', as: 'product' }}, // doosre collection se join karo
  { $unwind: '$user' },                                // array ko flat karo
  { $unwind: '$product' }                              // array ko flat karo
])

// Single field index (speeds up queries on email)
db.students.createIndex({ email: 1 })                  // index banao — search fast hoga

// Unique index (prevents duplicate emails)
db.students.createIndex({ email: 1 }, { unique: true }) // index banao — search fast hoga

// Compound index (queries filtering class AND marks)
db.students.createIndex({ class: 1, marks: -1 })       // index banao — search fast hoga

// Text search index
db.students.createIndex({ name: 'text', bio: 'text' }) // index banao — search fast hoga

// Text search query
db.students.find({ $text: { $search: 'Alice developer' } }) // documents dhundo

// Sort by text relevance score
db.students.find(                                      // documents dhundo
  { $text: { $search: 'Alice' } },
  { score: { $meta: 'textScore' } }
).sort({ score: { $meta: 'textScore' } })

// TTL index: auto-delete documents after 1 hour
db.sessions.createIndex(                               // index banao — search fast hoga
  { createdAt: 1 },
  { expireAfterSeconds: 3600 }
)

// List all indexes
db.students.getIndexes()

// Drop specific index
db.students.dropIndex({ email: 1 })

// Drop all indexes (except _id)
db.students.dropIndexes()

// Option 1: Text Index (fast, requires setup)
// Step 1: Create text index
db.articles.createIndex({ title: 'text', content: 'text' }) // index banao — search fast hoga

// Step 2: Search
db.articles.find({ $text: { $search: 'mongodb database' } }) // documents dhundo

// Boolean text search
db.articles.find({ $text: { $search: '"exact phrase"' } }) // documents dhundo
db.articles.find({ $text: { $search: 'mongodb -mysql' } })  // exclude mysql

// Option 2: Regex search (slower, no index needed)
db.students.find({ name: /alice/i })           // case insensitive
db.students.find({ name: /^Ali/i })            // starts with Ali
db.students.find({ email: /@gmail\.com$/i })   // ends with @gmail.com

// Option 3: $regex operator
db.students.find({ name: { $regex: 'ali', $options: 'i' } }) // documents dhundo

// Include specific fields (1 = include)
db.students.find(                                      // documents dhundo
  {},                               // no filter = all docs
  { name: 1, marks: 1, class: 1 }   // show only these fields
)
// NOTE: _id is included by default

// Exclude _id
db.students.find(                                      // documents dhundo
  { marks: { $gt: 80 } },                              // greater than
  { name: 1, marks: 1, _id: 0 }  // _id: 0 to hide it
)

// Exclude specific fields (0 = exclude)
db.students.find(                                      // documents dhundo
  {},
  { password: 0, __v: 0 }  // hide sensitive fields
)

// Nested field projection
db.students.find(                                      // documents dhundo
  {},
  { name: 1, 'address.city': 1, _id: 0 }
)

// Array slice: show only first 2 subjects
db.students.find(                                      // documents dhundo
  {},
  { name: 1, subjects: { $slice: 2 } }
)

// Count all documents
db.students.countDocuments()

// Count with filter
db.students.countDocuments({ marks: { $gt: 80 } })     // greater than
db.students.countDocuments({ class: '10th' })

// Estimated count (faster, uses metadata)
db.students.estimatedDocumentCount()

// Distinct: unique values
db.students.distinct('class')          // all unique class values
db.students.distinct('age')            // all unique ages

// Distinct with filter
db.students.distinct('name', { class: '10th' })

// Collection stats
db.students.stats()

// Database stats
db.stats()

// Find docs where subjects array contains 'Math'
db.students.find({ subjects: 'Math' })                 // documents dhundo

// Array contains ALL specified values
db.students.find({ subjects: { $all: ['Math', 'Physics'] } }) // documents dhundo

// Array size check
db.students.find({ subjects: { $size: 3 } })  // exactly 3 subjects

// elemMatch: array element matching condition
db.students.find({ scores: { $elemMatch: { $gt: 80, $lt: 95 } } }) // documents dhundo

// Push single element
db.students.updateOne(                                 // ek document update karo
  { name: 'Alice' },
  { $push: { subjects: 'Biology' } }                   // array mein add karo
)

// Push multiple elements
db.students.updateOne(                                 // ek document update karo
  { name: 'Alice' },
  { $push: { subjects: { $each: ['Biology', 'Art'] } } } // array mein add karo
)

// Add to set (no duplicates)
db.students.updateOne(                                 // ek document update karo
  { name: 'Alice' },
  { $addToSet: { subjects: 'Math' } }  // won't add if already exists
)

// Pull (remove) from array
db.students.updateOne(                                 // ek document update karo
  { name: 'Alice' },
  { $pull: { subjects: 'Math' } }
)

// Pull multiple values
db.students.updateOne(                                 // ek document update karo
  { name: 'Alice' },
  { $pullAll: { subjects: ['Math', 'Physics'] } }
)

// Check if field exists
db.students.find({ email: { $exists: true } })   // has email field
db.students.find({ email: { $exists: false } })  // missing email field

// Null check
db.students.find({ email: null })        // email is null OR missing
db.students.find({ email: { $ne: null } })  // email exists and not null

// Type check
db.students.find({ marks: { $type: 'double' } })  // marks is a number
db.students.find({ name:  { $type: 'string' } })  // name is a string
db.students.find({ _id:   { $type: 'objectId' } }) // objectId type

// Multiple type check
db.students.find({ age: { $type: ['int', 'double'] } }) // documents dhundo

// Convert type in aggregate
db.students.aggregate([                                // aggregation pipeline chalo
  { $project: {                                        // fields select karo
      name: 1,
      marks_str: { $toString: '$marks' },  // number to string
      age_int:   { $toInt: '$age' }         // string to int
  }}
])

// ── $cond: if-then-else inside aggregation ────────────────────
db.students.aggregate([                                // aggregation pipeline chalo
    {
        $project: {                                    // fields select karo
            name:  1,               // include name field
            marks: 1,               // include marks field
            grade: {
                $cond: {
                    if:   { $gte: ['$marks', 90] },  // if marks >= 90
                    then: 'A',                         // return 'A'
                    else: {
                        $cond: {
                            if:   { $gte: ['$marks', 75] },  // else if marks >= 75
                            then: 'B',                         // return 'B'
                            else: 'C'                          // else return 'C'
                        }
                    }
                }
            },
            bonus:   { $multiply: ['$marks', 0.1] },  // 10% of marks
            rounded: { $round: ['$marks', 1] }         // round to 1 decimal
        }
    }
])

// ── $switch: multiple conditions (like switch statement) ───────
db.students.aggregate([                                // aggregation pipeline chalo
    {
        $project: {                                    // fields select karo
            name: 1,
            performance: {
                $switch: {
                    branches: [                                         // list of cases
                        { case: { $gte: ['$marks', 90] }, then: 'Excellent' },  // case 1
                        { case: { $gte: ['$marks', 75] }, then: 'Good'      },  // case 2
                        { case: { $gte: ['$marks', 60] }, then: 'Average'   }   // case 3
                    ],
                    default: 'Below Average'    // if no case matches
                }
            }
        }
    }
])

// Check if index is being used
db.students.find({ marks: { $gt: 80 } }).explain('executionStats') // documents dhundo

// Look for 'IXSCAN' in executionStages (index used ✅)
// If you see 'COLLSCAN' = full collection scan ❌ (slow, add index)

// Check query execution time
db.students.find({ marks: { $gt: 80 } }).explain('allPlansExecution') // documents dhundo

// Profile slow queries (> 100ms)
db.setProfilingLevel(1, 100)
db.system.profile.find().sort({ ts: -1 }).limit(5)

// Index hint: force use of specific index
db.students.find({ marks: { $gt: 80 } }).hint({ marks: 1 }) // documents dhundo

// Disable index (force collection scan for testing)
db.students.find({ marks: { $gt: 80 } }).hint({ $natural: 1 }) // documents dhundo

// Collection stats (size, index info)
db.students.stats()
db.students.totalIndexSize()

// List all indexes with details
db.students.getIndexes()

