db.students.renameCollection('pupils')

// Copy collection
db.students.aggregate([                                // aggregation pipeline chalo
  { $match: {} },                                      // documents filter karo
  { $out: 'students_backup' }  // output to new collection
])

// Drop collection
db.students.drop()                                     // collection delete karo

// Drop database
db.dropDatabase()                                      // database delete karo

// Current operations
db.currentOp()

// Kill slow operation
db.killOp(opid)

// Server status
db.serverStatus()

// User management
