    { name: 'Alice',   age: 20, class: '10th', marks: 92.5, email: 'alice@example.com' },
    { name: 'Bob',     age: 21, class: '11th', marks: 78.0, email: 'bob@example.com'   },
    { name: 'Charlie', age: 19, class: '10th', marks: 85.5, email: 'charlie@test.com'  },
    { name: 'Diana',   age: 20, class: '12th', marks: 95.0, email: 'diana@example.com' }
])

// Step 3: Find all
db.students.find().pretty()                            // documents dhundo

// Step 4: Find top students
db.students.find({ marks: { $gt: 85 } }).sort({ marks: -1 }) // documents dhundo

// Step 5: Count
db.students.countDocuments()

use school_db                                          // database switch karo

// Insert teachers
db.teachers.insertMany([                               // multiple documents insert karo
    { name: 'Mr. Sharma', subject: 'Mathematics', age: 45, salary: 55000, email: 'sharma@school.com' },
    { name: 'Ms. Priya',  subject: 'Science',     age: 38, salary: 48000, email: 'priya@school.com'  },
    { name: 'Mr. Verma',  subject: 'English',     age: 52, salary: 60000, email: 'verma@school.com'  }
])

// Find all teachers
db.teachers.find().pretty()                            // documents dhundo

// Find by subject
db.teachers.find({ subject: 'Mathematics' })           // documents dhundo

// Find with salary filter
db.teachers.find({ salary: { $gt: 50000 } }).sort({ salary: -1 }) // documents dhundo

// Update salary
db.teachers.updateOne(                                 // ek document update karo
    { name: 'Mr. Sharma' },
    { $set: { salary: 60000 } }                        // field update karo
)

// $expr: compare two fields
db.students.find({                                     // documents dhundo
    $expr: { $gt: ['$marks', '$passing_marks'] }       // greater than
})

// Find students where marks > age * 3
db.students.find({                                     // documents dhundo
    $expr: { $gt: ['$marks', { $multiply: ['$age', 3] }] } // greater than
})

// Multiple conditions with $and
db.students.find({                                     // documents dhundo
    $and: [                                            // dono conditions True hon
        { marks: { $gte: 60 } },                       // greater than or equal
        { age:   { $lte: 22 } },                       // less than or equal
        { class: { $in: ['10th', '11th'] } }           // list mein se match karo
    ]
})

// $not operator
db.students.find({                                     // documents dhundo
    marks: { $not: { $lt: 60 } }  // marks NOT less than 60
})

// $regex with options
db.students.find({                                     // documents dhundo
    name: { $regex: '^A', $options: 'i' }  // starts with A
})

// One-to-many relationship example
// Step 1: Create departments
db.departments.insertMany([                            // multiple documents insert karo
    { _id: 'eng',  name: 'Engineering' },
    { _id: 'mkt',  name: 'Marketing'   },
    { _id: 'hr',   name: 'HR'          }
])

// Step 2: Create employees with dept reference
db.employees.insertMany([                              // multiple documents insert karo
    { name: 'Alice',   dept_id: 'eng', salary: 75000 },
    { name: 'Bob',     dept_id: 'mkt', salary: 65000 },
    { name: 'Charlie', dept_id: 'eng', salary: 80000 }
])

// Step 3: Lookup (JOIN)
db.employees.aggregate([                               // aggregation pipeline chalo
    {
        $lookup: {                                     // doosre collection se join karo
            from:         'departments',
            localField:   'dept_id',
            foreignField: '_id',
            as:           'department'
        }
    },
    { $unwind: '$department' },                        // array ko flat karo
    { $project: { name: 1, salary: 1, 'department.name': 1, _id: 0 } } // fields select karo
])

// MongoDB Transactions — ACID guarantees for multiple operations
// Requires: MongoDB 4.0+ and Replica Set (or Atlas cluster)
// Useful when you need ALL operations to succeed or ALL to fail

const session = db.getMongo().startSession()    // create a session
const studentsColl = session.getDatabase('school_db').students  // get collection via session
const auditColl    = session.getDatabase('school_db').audit     // another collection

try {
    session.startTransaction()   // begin transaction — all following ops are atomic

    // Operation 1: update student marks
    studentsColl.updateOne(
        { name: 'Alice' },           // filter: find Alice
        { $set: { marks: 95 } }      // update: set marks to 95
    )

    // Operation 2: log the change in audit collection
    auditColl.insertOne({
        action:    'marks_updated',   // what happened
        student:   'Alice',           // who was affected
        new_marks: 95,                // new value
        timestamp: new Date()         // when it happened
    })

    session.commitTransaction()       // SUCCESS: save all changes permanently
    print('Transaction committed successfully!')

} catch (error) {
    session.abortTransaction()        // FAILURE: undo ALL changes (rollback)
    print('Transaction failed, rolled back:', error)

} finally {
    session.endSession()              // always cleanup the session
}

// Create collection with geo index
db.places.createIndex({ location: '2dsphere' })        // index banao — search fast hoga

// Insert places with coordinates [longitude, latitude]
db.places.insertMany([                                 // multiple documents insert karo
    { name: 'Mumbai',    location: { type: 'Point', coordinates: [72.8777, 19.0760] } },
    { name: 'Delhi',     location: { type: 'Point', coordinates: [77.1025, 28.7041] } },
    { name: 'Bangalore', location: { type: 'Point', coordinates: [77.5946, 12.9716] } }
])

// Find places near a point (within 500km)
db.places.find({                                       // documents dhundo
    location: {
        $near: {
            $geometry: { type: 'Point', coordinates: [72.8777, 19.0760] },
            $maxDistance: 500000  // 500km in meters
        }
    }
})

// Find places within a circle
db.places.find({                                       // documents dhundo
    location: {
        $geoWithin: {
            $centerSphere: [[72.8777, 19.0760], 5 / 3963.2]  // 5 mile radius
        }
    }
})

// Faceted search — get results + counts in one query
db.products.aggregate([                                // aggregation pipeline chalo
  { $match: { status: 'active' } },                    // documents filter karo
  {
    $facet: {
      byCategory: [
        { $group: { _id: '$category', count: { $sum: 1 } } }, // documents group karo
        { $sort: { count: -1 } }                       // documents sort karo
      ],
      priceRanges: [
        { $bucket: { groupBy: '$price',
            boundaries: [0, 100, 500, 1000, 5000],
            default: '5000+',
            output: { count: { $sum: 1 }, avg: { $avg: '$price' } } // sum nikalo
        }}
      ],
      totalCount: [ { $count: 'total' } ]
    }
  }
])

