// Join orders -> users -> products in one pipeline
db.orders.aggregate([                                  // aggregation pipeline chalo
  {
    $lookup: {                                         // doosre collection se join karo
      from: 'users',
      localField: 'user_id',
      foreignField: '_id',
      as: 'user'
    }
  },
  { $unwind: '$user' },                                // array ko flat karo
  { $unwind: '$items' },                               // array ko flat karo
  {
    $lookup: {                                         // doosre collection se join karo
      from: 'products',
      localField: 'items.product_id',
      foreignField: '_id',
      as: 'items.product'
    }
  },
  { $unwind: '$items.product' },                       // array ko flat karo
  {
    $project: {                                        // fields select karo
      orderId: 1,
      'user.name': 1,
      'user.email': 1,
      'items.quantity': 1,
      'items.product.name': 1,
      'items.product.price': 1
    }
  }
])

// Efficient pagination with total count
async function getPaginated(collection, filter, page, pageSize) {
  const result = await collection.aggregate([
    { $match: filter },                                // documents filter karo
    {
      $facet: {
        data: [
          { $sort: { createdAt: -1 } },                // documents sort karo
          { $skip: (page - 1) * pageSize },
          { $limit: pageSize }                         // result limit karo
        ],
        total: [ { $count: 'count' } ]
      }
    }
  ]).toArray();

  return {
    data: result[0].data,
    total: result[0].total[0]?.count || 0,
    page,
    pages: Math.ceil((result[0].total[0]?.count || 0) / pageSize)
  };
}

